package com.mentalmadad.repository; import com.mentalmadad.entity.Doctor; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import java.util.*;
public interface DoctorRepository extends JpaRepository<Doctor,Long> { Page<Doctor> findBySpecializationContainingIgnoreCase(String specialization, Pageable p); @Query("select d from Doctor d where (:specialization is null or lower(d.specialization) like lower(concat('%',:specialization,'%'))) and (:name is null or lower(concat(d.user.firstName,' ',d.user.lastName)) like lower(concat('%',:name,'%'))) ") Page<Doctor> search(String specialization,String name,Pageable p); }
